from pathlib import Path
import json,re,sys,hashlib,sqlite3,datetime
P=Path(__file__).resolve().parent;L=P.parents[3];sys.path.insert(0,str(L))
import substantive_impact as impact
from run_exhaustive import validate_answer
from ingest import source_notes
sha=lambda x:hashlib.sha256(x if isinstance(x,bytes)else(x or'').encode()).hexdigest()
sources=json.loads((P/'source.json').read_text());by={x['number']:x for x in sources};rows={}
def paras(*items):return ''.join('<p>'+x+'</p>' for x in items)
def add(n,body,reason,review,benefit,classification,assessment,limits,burdens,effect=None):
 s=by[n];row={k:s[k]for k in ['code_id','source_id','source_sha256','number']};row.update(status='rewrite_draft'if body is not None else'retained_unchanged',proposed_xml=body,reason=reason,review_notes=review,benefit_review=benefit,substantive_impact=dict(version=1,classification=classification,assessment=assessment,scope_limitations=limits,new_burdens_review=burdens,effects=[]))
 if effect:
  kind,measure,description,before,after,population,conditions,replacements,sourcequote,proposedquote=effect
  row['substantive_impact']['effects']=[dict(kind=kind,measure_id=measure,description=description,before=before,after=after,unit='legal_duty',affected_population=population,conditions_and_transition=conditions,replacement_or_new_burdens=replacements,source_quote=sourcequote,proposed_quote=proposedquote)]
 impact.validate(row,s,required=True);rows[n]=row
base_limits='Examen borné à cet article et au circuit social capturé ; les autres règles et leurs fondements autonomes restent distincts. Aucune économie nationale ni réduction nette globale des prélèvements n’est chiffrée.'
base_review='Source officielle et notes lues en entier. Proposition non enregistrée, soumise à la contrelecture du parent. Les empreintes de la source, des notes, des politiques et des cibles doivent être revérifiées avant inscription ; aucun certificat technique ne vaut validation juridique du fond.'

n='L242-14';body=paras(
"L’exclusion de l’assiette des cotisations de sécurité sociale prévue au 6° du II de l’article L. 242-1 s’applique dans les conditions de fond fixées par ce dernier article et par les dispositions auxquelles il renvoie. Elle n’est pas subordonnée à une notification distincte à l’organisme de recouvrement de l’identité des salariés ou mandataires sociaux attributaires, du nombre ou de la valeur des actions attribuées. Le défaut d’une telle notification ne rend pas l’employeur redevable de la totalité des cotisations, y compris de leur part salariale.",
"La même règle s’applique lorsque les actions sont attribuées par une société dont le siège est situé à l’étranger et qui est mère ou filiale de l’entreprise dans laquelle l’attributaire exerce son activité.",
"Les déclarations de rémunérations, les obligations fiscales, la justification des conditions de fond de l’exclusion et les pouvoirs de contrôle qui reposent sur un autre fondement restent applicables dans leur champ. Aucune déclaration ni attestation de remplacement n’est créée par le présent article.",
"Ces dispositions s’appliquent aux cotisations et contributions dues pour les périodes courant à compter de l’entrée en vigueur de la loi qui les institue. Les périodes antérieures, les créances, les exclusions d’assiette, les régularisations, les restitutions, les prescriptions et les recours correspondants restent soumis aux règles qui leur étaient applicables.")
add(n,body,'Supprime la notification autonome conditionnant l’exclusion d’assiette des actions et l’assujettissement intégral, part salariale comprise, attaché à son seul défaut.',base_review+' L242-1 II,6° conserve le fondement d’exclusion ; le présent texte ne change ni ses conditions fiscales de fond ni les taxes autonomes sur les actions. La transition vise les périodes de cotisations et non une date inventée de promulgation.',
'Le bénéfice du 6° du II de L242-1 reste ouvert aux situations futures remplissant ses conditions de fond, y compris les attributions par une mère ou filiale étrangère. La formalité autonome et sa perte automatique d’exclusion sont retirées ; les périodes antérieures gardent leurs exclusions, créances et recours propres. Aucun prélèvement nouveau ni rétrécissement de l’assiette exonérée n’est créé.',
'material_reduction','L’article source imposait une notification annuelle distincte et faisait payer toutes les cotisations à l’employeur en cas de défaut. Ces deux conséquences autonomes sont retirées pour les périodes nouvelles ; l’exclusion et ses conditions de fond subsistent.',base_limits+' Les déclarations fiscales ou de paie autonomes ne sont pas supprimées par cette coupe.',
'Aucune attestation ou déclaration de remplacement n’est imposée. Les contrôles des conditions de fond et les déclarations ayant une autre base légale demeurent ; aucun montant national de cotisations évitées n’est déduit de la sanction retirée.',
('obligation_removed','actions-notification-exoneration','Fin de la notification autonome et de la déchéance automatique de l’exclusion d’assiette.',
'Notification de l’identité des attributaires, du nombre et de la valeur des actions de l’année précédente ; à défaut, paiement de toutes les cotisations par l’employeur, part salariale comprise.',
'Aucune notification autonome sur ce fondement et aucune déchéance pour son seul défaut ; conditions matérielles du 6° du II de L242-1 et contrôles indépendants conservés.',
'Employeurs et attributaires visés par L242-1 II,6°, y compris actions de sociétés mères ou filiales étrangères.',
'Périodes nouvelles à compter de l’entrée en vigueur de la loi proposée ; périodes antérieures et recours selon leur régime, sans remise rétroactive générale.',
'Pas de déclaration de remplacement ; déclarations de paie, fiscales et conditions de fond autonomes conservées.',
"A défaut, l'employeur est tenu au paiement de la totalité des cotisations sociales, y compris pour leur part salariale.",
'Le défaut d’une telle notification ne rend pas l’employeur redevable de la totalité des cotisations, y compris de leur part salariale.'))

n='R133-13';old=by[n]['source_xml'];replacement=('<p>2° La fin effective du contrat de travail. Pour le contrat unique à durée indéterminée, la fin d’une mission, d’une affectation, d’une formation ou d’une tâche sans rupture de l’emploi ne constitue pas cet événement. La notification d’une rupture ne se substitue pas à sa date de fin effective ; les délais et dispenses de transmission restent ceux de l’article R. 133-14.</p>');assert old.count('<p>2° La fin du contrat de travail.</p>')==1;body=old.replace('<p>2° La fin du contrat de travail.</p>',replacement)
add(n,body,'Coordonne le seul événement de fin de contrat avec l’emploi unique sans terme : la fin d’une mission ne déclenche pas une déclaration fictive de rupture.',base_review+' Les six divisions, les informations de santé et de congé supplémentaire de naissance, les circuits URSSAF/MSA, la norme, le certificat technique, les cinq rubriques de compte rendu et les sanctions restent intacts. R133-14 proposé fixe les délais et dispenses ; pas de nouvelle règle de calcul d’indemnité ou de rupture dans la norme déclarative.',
'Les exonérations restent déclarées avec leur nomenclature, les événements de santé conservent leurs délais et leurs droits, et le compte rendu ne devient pas un quitus juridique. Le contrat unique ne transforme pas la fin d’affectation en chômage ou en rupture et ne retire aucune rémunération d’intermission ni droit antérieur.',
'coordination_only','La coordination précise l’événement déjà déclaré ; elle ne crée pas une nouvelle déclaration ni une baisse d’impôt. Toutes les données de cotisations, de santé et de droits demeurent dans leur champ et les dispenses de R133-14 proposé restent disponibles.',base_limits+' Le délai de préavis et le barème relèvent des articles centraux du travail, sans nouvelle économie imputée à ce renvoi.',
'Aucun nouveau champ, signalement de mission, régime d’immatriculation ni délai n’est ajouté. La fin effective de l’emploi reste distincte de la notification, du dernier jour travaillé et des paiements de préavis ou de dommages.',
('coordination','contract-unique','Déclaration de la fin de l’emploi, distincte de la fin de mission.',
'L’événement déclaré est la fin du contrat de travail, sans distinction explicite entre mission et emploi dans cet article.',
'L’événement reste la fin effective de l’emploi ; une mission achevée sans rupture du contrat unique ne le déclenche pas.',
'Employeurs relevant de la DSN, notamment entreprises de travail temporaire et salariés du contrat unique.',
'Règles des contrats anciens conservées à leurs fondements ; délais et dispenses régis par R133-14, sans suppression des droits maladie, chômage, congés ou rémunération garantis.',
'Aucun nouveau signalement de mission ; coordination de la mesure contract-unique, sans la recompter comme un autre allègement.',
'2° La fin du contrat de travail.',
'2° La fin effective du contrat de travail. Pour le contrat unique à durée indéterminée, la fin d’une mission, d’une affectation, d’une formation ou d’une tâche sans rupture de l’emploi ne constitue pas cet événement.'))

n='R133-44';body=by[n]['source_xml'];last="Le tiers déclarant dispose d'un délai de huit jours à compter de la date de réception de la notification de la décision de retrait pour informer ses clients et d'un délai d'un mois pour restituer l'ensemble des pièces justificatives leur appartenant qui sont en sa possession.";assert last in body
new="Le tiers déclarant restitue à ses clients l’ensemble des pièces justificatives leur appartenant qui sont en sa possession dans le délai d’un mois à compter de la réception de la notification de la décision de retrait. Aucune seconde notification de cette décision par le tiers déclarant à ses clients n’est exigée ; l’information de ceux-ci demeure assurée par la notification de l’organisme prévue au premier alinéa du présent III. Cette suppression s’applique aux notifications de retrait reçues à compter de l’entrée en vigueur du présent décret ; elle ne retire ni les droits de défense, ni les recours, ni l’obligation de restitution des pièces."
body=body.replace(last,new)
add(n,body,'Retire l’avis supplémentaire sous huit jours par le mandataire déjà sanctionné : l’organisme notifie lui-même chaque client ; la restitution sous un mois demeure.',base_review+' Les infractions, le contradictoire d’un mois, la décision motivée, les voies de recours, le plafond de cinq ans et la sanction personnelle dans une structure sont reproduits sans changement. Pas de tolérance de fraude ni suppression de l’information des clients.',
'Les clients conservent la notification datée de l’organisme, la restitution de leurs pièces sous un mois et leurs droits sociaux. Le mandataire conserve contradictoire et recours ; la sanction reste limitée à son auteur, cinq ans au plus. Supprimer une seconde lettre ne supprime aucun droit à correction, exonération ou remboursement.',
'material_reduction','Une seule notification par l’organisme remplace le double avis organisme puis mandataire sous huit jours. Cette coupe précise ne réduit ni la prévention de la fraude ni le délai de restitution des justificatifs.',base_limits+' Les autres modalités du mandat et les sanctions pénales autonomes restent distinctes.',
'Aucun nouveau courrier, portail ou justificatif n’est demandé au mandataire ou au client. La notification par l’organisme et la restitution sous un mois étaient déjà dues dans la source et ne sont pas des charges créées en remplacement.',
('obligation_removed','mandataire-double-avis-retrait','Suppression de la seconde information des clients sous huit jours.',
'L’organisme notifie la décision aux clients ; le mandataire doit encore les informer sous huit jours et restituer les pièces sous un mois.',
'Une notification de l’organisme ; plus de seconde information obligatoire par le mandataire, restitution sous un mois maintenue.',
'Tiers déclarants sanctionnés et leurs clients auprès des organismes de sécurité sociale.',
'Notifications reçues après entrée en vigueur du décret proposé ; fraude sanctionnée, contradictoire, recours et restitution conservés.',
'Aucune formalité de remplacement ; l’organisme doit toujours notifier chaque client avec preuve de réception.',
last,new))

n='R242-3';body=paras(
"Pour appliquer le premier alinéa de l’article L. 242-3, les informations nécessaires à la répartition du plafond entre employeurs sont réutilisées lorsqu’elles sont déjà légalement détenues et à jour ou légalement accessibles pour cette finalité. Aucune déclaration du salarié sur un modèle arrêté par le ministre ni transmission répétée des mêmes informations n’est alors exigée. Cette réutilisation respecte les secrets protégés et ne donne pas à un employeur accès à l’ensemble des déclarations d’un autre employeur.",
"Lorsque ces informations ne suffisent pas à déterminer la répartition, les personnes concernées font connaître à chacun de leurs employeurs, à la fin du mois ou du trimestre, le total des rémunérations perçues au cours de cette période dans la seule mesure nécessaire au calcul. Elles peuvent utiliser les documents existants comportant les informations utiles ; aucun modèle obligatoire ni attestation distincte n’est exigé.",
"Le travailleur à domicile assuré obligatoire communique, dans les cinq premiers jours de chaque trimestre, aux chefs d’entreprise pour lesquels il travaille les noms, numéros d’immatriculation et salaires des personnes ayant travaillé avec lui au cours du trimestre précédent pour le compte de ces employeurs, seulement pour les informations manquantes, inexactes ou périmées qui ne sont pas déjà légalement détenues ou accessibles pour ce calcul. Les documents ordinaires contenant ces informations peuvent être réutilisés sans déclaration distincte. Si les informations nécessaires restent manquantes, les chefs d’entreprise en avisent l’organisme chargé du recouvrement ; ils ne renouvellent pas cet avis pour les mêmes données déjà signalées tant que leur situation n’a pas changé.",
"Les mêmes règles s’appliquent au salarié ou assimilé qui se fait assister ou remplacer par un membre de sa famille, un aide ou un remplaçant qu’il recrute ou rémunère pour une activité exercée au profit de son employeur.",
"Lorsque les informations nécessaires à la répartition ne sont pas disponibles, chaque employeur calcule les cotisations sur la rémunération totale qu’il verse, compte tenu de l’article R. 242-2. Le seul défaut d’un formulaire ou d’une transmission en double ne fait pas obstacle à une répartition dont les éléments sont disponibles. Toute partie intéressée peut provoquer le remboursement des cotisations versées en trop. En cas de désaccord, l’article R. 242-4 reste applicable.",
"Le présent article ne s’applique pas lorsqu’un employeur met en œuvre la dérogation prévue au deuxième alinéa de l’article L. 242-3. Il ne modifie ni les règles de plafond et de prorata, ni les déclarations et les droits propres des personnes qui ont effectivement travaillé, ni les droits à retraite déjà constitués.",
"Ces dispenses de modèle et de transmission répétée s’appliquent aux formalités restant à accomplir à compter de l’entrée en vigueur du présent décret, sans exiger de refaire les déclarations antérieures. Les créances, régularisations, restitutions, prescriptions et recours portant sur les périodes antérieures conservent leur régime.")
add(n,body,'Supprime le modèle ministériel obligatoire et les preuves multi-employeurs répétées lorsque les données de plafond sont déjà disponibles ; conserve les informations manquantes, le calcul et les restitutions.',base_review+' L242-3 conserve le prorata et la voie alternative à temps partiel. R242-2 conserve les plafonds, exclusions et régularisations, R242-4 le règlement des désaccords. Les travailleurs à domicile et les aides ne disparaissent ni de la protection sociale ni des déclarations autonomes ; cinq premiers jours du trimestre conservés pour le résiduel, sans échéance mensuelle nouvelle.',
'Le prorata entre employeurs, les alternatives favorables de L242-3, le remboursement des excédents et le recours en désaccord sont conservés. Aucun accès général aux rémunérations d’un autre employeur n’est créé ; le formulaire supprimé ne conditionne plus un avantage dont les données sont connues. Les anciens droits à retraite et les droits sociaux des aides restent protégés.',
'material_reduction','La source exige une déclaration sur modèle chaque mois ou trimestre et des signalements trimestriels même déjà documentés. Le projet retire le modèle et les communications répétées, réutilise les documents existants et garde seulement les renseignements effectivement manquants avec les échéances résiduelles antérieures.',base_limits+' L’accès légal et effectif aux données conditionne la dispense : aucune interconnexion totale de DSN ni disponibilité technique générale n’est supposée.',
'Aucun registre, identifiant ou abonnement nouveau n’est créé. Les informations manquantes de rémunération, d’identité et de salaire étaient déjà dues ; elles ne sont ni élargies ni avancées. Les mêmes avis manquants ne sont pas répétés, mais les changements pertinents restent signalés.',
('obligation_removed','plafond-multi-employeurs-doublons','Suppression du modèle obligatoire et des transmissions répétées de données de plafond disponibles.',
'Modèle ministériel de déclaration en fin de mois ou trimestre ; données trimestrielles des aides et avis du défaut même lorsque les pièces sont déjà disponibles.',
'Pas de modèle ni de seconde transmission de données légalement disponibles et à jour ; pièces ordinaires acceptées, renseignements manquants aux anciennes échéances, remboursement et arbitrage conservés.',
'Salariés multi-employeurs, travailleurs à domicile, aides ou remplaçants concernés et leurs employeurs.',
'Formalités futures ou restant à accomplir après le décret ; aucune déclaration passée à refaire, anciens recours et créances conservés ; dérogation de L242-3 deuxième alinéa inchangée.',
'Pas de nouveau flux ou registre ; déclaration résiduelle de données manquantes, confidentialité et droits des personnes ayant travaillé maintenus.',
'Elles utilisent, à cet effet, une déclaration du modèle arrêté par le ministre chargé de la sécurité sociale.',
'Elles peuvent utiliser les documents existants comportant les informations utiles ; aucun modèle obligatoire ni attestation distincte n’est exigé.'))

n='D242-2-2';body=paras(
"La personne tierce mentionnée au sixième alinéa de l’article L. 242-1-4 informe l’employeur du montant des sommes et avantages alloués à son salarié et du montant des cotisations et contributions acquittées sur ceux-ci. Cette information peut résulter de tout document ou échange existant comportant ces éléments et effectivement communiqué à l’employeur. Il n’est exigé ni copie obligatoire du document adressé au salarié, ni document ou transmission supplémentaire lorsque l’employeur a déjà reçu l’ensemble de ces informations.",
"Les informations manquantes sont communiquées au plus tard, au choix de la personne tierce, le premier jour du mois suivant l’allocation des sommes et avantages ou le 30 juin de l’année civile suivant celle de cette allocation. Les informations déjà communiquées n’ont pas à être répétées ; les données inexactes sont rectifiées dans le cadre des obligations qui leur sont applicables.",
"Le présent article ne modifie ni les cotisations et contributions dues, ni la contribution libératoire, sa franchise, son plafond et ses exclusions prévus à l’article L. 242-1-4, ni les obligations d’information du salarié reposant sur un autre fondement. La dispense de copie ou de transmission répétée s’applique aux formalités restant à accomplir à compter de l’entrée en vigueur du présent décret ; elle n’impose de refaire aucun document antérieur.")
add(n,body,'Remplace la copie obligatoire du document salarié par la réutilisation des informations déjà remises à l’employeur, avec les mêmes échéances au choix du tiers.',base_review+' Le sixième alinéa de L242-1-4 est bien l’habilitation réglementaire ; son quatrième alinéa impose l’information de l’employeur. Les deux échéances alternatives sont conservées, sans transformer le premier jour du mois en échéance obligatoire pour tous.',
'La contribution libératoire de 20 % de L242-1-4, sa franchise annuelle égale à 15 % du SMIC mensuel, la limite de 1,5 SMIC mensuel annuel et les exclusions intragroupe ou de fraude restent intégrales. Le tiers informe toujours l’employeur des montants utiles ; l’information autonome du salarié n’est pas supprimée. La dispense de copie profite aux situations futures également.',
'material_reduction','Le texte source impose une copie spécifique même si les deux montants sont déjà connus de l’employeur. Le projet retire ce document et toute seconde transmission inutile ; il conserve l’information légale et le choix des deux délais.',base_limits+' Aucune baisse du taux de 20 % ni des cotisations sur la fraction supérieure au plafond n’est revendiquée.',
'Aucune attestation nouvelle ni information supplémentaire n’est demandée. Les montants d’avantages et de cotisations étaient déjà requis ; le choix du 30 juin suivant reste disponible. La simple détention par une administration ne suffit pas : l’employeur doit avoir effectivement reçu les données.',
('obligation_removed','avantages-tiers-copie-double','Fin de la copie obligatoire lorsque l’employeur possède déjà les informations utiles.',
'Copie à l’employeur du document du salarié avec montants d’avantages et de cotisations, même si les mêmes informations ont déjà été remises.',
'Tout document ou échange existant suffit ; plus de copie ni d’envoi supplémentaire si l’employeur a déjà reçu tous les éléments, aux mêmes échéances alternatives.',
'Tiers versant des avantages à des salariés d’un autre employeur dans le champ de L242-1-4.',
'Formalités restant à accomplir après le décret proposé ; montants, exonérations, délais et obligations autonomes du salarié conservés.',
'Pas de déclaration de remplacement ; communication seulement des informations encore manquantes, sans nouveau taux ni changement d’assiette.',
'La personne tierce mentionnée au sixième alinéa de l’article L. 242-1-4' if False else impact.plain(by[n]['source_xml']).split('Cette transmission')[0].strip(),
'Il n’est exigé ni copie obligatoire du document adressé au salarié, ni document ou transmission supplémentaire lorsque l’employeur a déjà reçu l’ensemble de ces informations.'))

# Article-specific necessity decisions: exact original body is retained, never copied into a purported redraft.
kept={
'R243-29':('Conserve l’information au moins annuelle du bénéficiaire sur les quatre catégories de montants des revenus de remplacement.','La source ne prescrit pas de relevé annuel distinct : des décomptes mensuels effectivement reçus couvrant toutes les rubriques peuvent déjà satisfaire une information au moins annuelle. Présenter cette faculté comme une nouvelle suppression ferait compter une simple clarification. La transmission DSN à l’administration ne remplace pas l’information du bénéficiaire ; montants brut et net, cotisations, retenue fiscale et avant impôt restent communiqués, sans nouvelle inscription.'),
'L242-1-3':('Conserve la transmission inter-organismes nécessaire à la correction des droits sociaux et des droits à retraite complémentaire après redressement ou correction de DSN.','Les informations passent entre organismes habilités plutôt que par une nouvelle preuve à la charge du salarié ; leur retrait ferait perdre des rectifications favorables de droits déjà constitués. L’arrêté circonscrit destinataires et données ; aucune nouvelle déclaration patronale n’est créée.'),
'L242-1-4':('Conserve le régime autonome des avantages versés par un tiers et sa contribution libératoire favorable ; ne transpose aucune abrogation d’un autre prélèvement à ce régime.','Taux de 20 % sur la tranche annuelle au-delà de 15 % du SMIC mensuel, jusqu’à 1,5 SMIC mensuel, cotisations ordinaires au-dessus ; exclusions intragroupe et fraude maintenues. Le changement de contrat ne retire pas cet avantage aux salariés futurs. D242-2-2 porte seul la suppression de copie répétée, sans modifier les taux ni l’assiette.'),
'L242-3':('Conserve la répartition proportionnelle du plafond entre employeurs et les voies favorables alternatives ; les justificatifs répétés sont traités à R242-3.','La voie proportionnelle évite un plafond entier multiplié par employeur ; l’alternative de temps partiel et les forfaits ou abattements sectoriels restent ouverts aux situations futures. Aucun double avantage ni nouveau taux n’est créé ; la continuité du contrat unique ne supprime pas la pluralité d’employeurs.'),
'L242-8':('Conserve l’abattement de plafond favorable au temps partiel et son renvoi à la définition du travail à temps partiel.','L3123-1 proposé conserve les références hebdomadaire, mensuelle et annuelle avec 1 607 heures dans son champ, sans restaurer le plancher général de 24 heures supprimé. Retirer cet abattement augmenterait des cotisations pour les futurs temps partiels ; les droits et remboursements antérieurs restent intacts.'),
'L242-9':('Conserve l’application de l’abattement à chaque échéance et sa limite quand les heures complémentaires atteignent le temps normal de l’établissement.','La condition vérifie la réalité du temps partiel et ne rétablit aucun minimum de 24 heures. La durée normale de l’établissement ne devient pas mécaniquement 40 heures pour tous ; le contrat écrit et les heures réellement accomplies restent la base. Les bénéfices restent disponibles pour tout futur temps partiel éligible.'),
'L242-10':('Conserve les exclusions de cumul et les champs spéciaux du mécanisme de plafond ; aucune extension non instruite du régime intérimaire ou de l’activité partielle.','Les forfaits et taux spécifiques, le plafond déjà fractionné et les régimes intérim/activité partielle ne sont pas abolis par le contrat unique. L242-8/9 et R242-2 doivent être évalués ensemble avant une extension ; aucune disparition d’exonération éligible n’est proposée ici, ni réduction des rémunérations d’intermission, ni retrait de droits antérieurs.'),
'R133-14-1':('Conserve l’échéance de DSN des revenus de remplacement, le téléservice et la prorogation favorable au jour ouvrable suivant.','Le dixième jour du mois suivant s’articule avec le paiement de R243-27 ; le modifier seul déplacerait le financement et les données sociales sans suppression démontrée de charge. Aucun paiement nationalement réduit n’est déduit du calendrier, et la protection des bénéficiaires et du jour non ouvré reste entière.'),
'R133-14-2':('Conserve le circuit contradictoire des anomalies, le délai minimal de trente jours et la faculté de contester les corrections.','L133-5-3-1 impose encore la correction par le déclarant ; une réécriture réglementaire ne peut prétendre supprimer cette obligation. Les corrections d’office non contestées et le recouvrement contesté sont distingués ; le projet de L133-5-3-1 permet la propagation des corrections sans créer une seconde procédure. Le droit de contestation et les rectifications favorables restent ouverts.'),
'R133-14-3':('Conserve la substitution de DSN corrigée et l’information distincte de l’employeur et des salariés dont les droits peuvent être affectés.','Supprimer l’information des salariés empêcherait d’exercer des recours sur prestations et retraite. La substitution évite de maintenir deux déclarations concurrentes ; ni la notification de dette ni la transmission réglementaire ne créent une nouvelle taxe. R244-1 garantit toujours cause, nature, montant et périodes des sommes réclamées.'),
'R133-14-4':('Conserve l’information préalable et la réponse motivée aux observations avant recouvrement d’une correction contestée.','Le contradictoire protège la contestation d’un redressement et des droits sociaux associés ; ce n’est pas un formulaire redondant de l’employeur. L’assiette de dette et les voies de recours restent régies par les fondements autonomes ; aucune contestation n’est réputée abandonnée et aucun avantage favorable n’est fermé.'),
'R133-14-5':('Conserve l’obligation pour l’organisme de signaler le trop-versé et les modalités de remboursement ou d’imputation.','La suppression de cette information ferait perdre un outil concret de restitution aux entreprises et aux particuliers éligibles. Les nouveaux emplois et les contrats anciens conservent la même possibilité de restitution ; aucun remboursement automatique sans créance ni nouvelle taxe n’est créé. La norme ne prescrit aucune attestation supplémentaire au cotisant.'),
'R133-14-6':('Conserve la distinction entre correction technique de déclaration et constatation de fond par les agents de contrôle.','Un compte rendu de conformité ne vaut pas certificat de légalité des exonérations ou des droits. La règle maintient les contrôles de fond autonomes sans imposer un second dépôt ou une nouvelle inscription ; elle ne retire aucune possibilité de contestation, réduction ou remboursement. La suppression de doublons déclaratifs ne doit pas devenir un quitus de fraude.'),
'R133-15':('Conserve la gradation favorable des pénalités des dispositifs simplifiés et leurs voies de remise ; pas de retrait d’un taux réduit sous prétexte de fusion.','Les particuliers conservent 0,5 % du plafond mensuel par déclaration manquante et 0,25 % en cas de rémunération minorée, ainsi que les règles R243-11/19/20. La pénalité légale L133-5-4 ne peut être abolie dans ce seul article réglementaire. Les références 1°,2° et 3°,4°,6°,7°,8° de L133-5-6 ont été vérifiées sans élargissement du champ des sanctions.'),
'R133-16':('Conserve la protection des cotisations salariales et de l’impôt déjà précompté comme condition d’accès à l’échéancier.','R243-21 ouvre un échéancier pour les dettes patronales mais exige déjà le reversement salarial ; l’alléger isolément permettrait de conserver des sommes prélevées au salarié. Les facilités de paiement restantes et leur demande demeurent ; aucune cotisation nouvelle ni avance sur une dette inexistante n’est créée. La sanction du détournement de retenue fiscale reste distincte des erreurs de bonne foi.'),
'R133-43':('Conserve le mandat librement choisi, la présomption professionnelle, l’information du client et la responsabilité du déclarant.','La déclaration de mission est déjà réputée faite via les déclarations existantes ; aucun second agrément ne figure dans la source. La vérification de la relation protège le consentement du client et n’impose pas ici une copie répétée. Une suppression de doublon éventuel de pratique administrative ne justifie pas une nouvelle réécriture sans effet démontré. R133-44 porte seul la coupe de la seconde notification de retrait.'),
'R242-4':('Conserve l’arbitrage du partage d’assiette entre employeurs par l’organisme de recouvrement et la voie en cas de carence.','Cette décision permet de faire appliquer le plafond et de résoudre un désaccord sans partager tous les salaires avec chaque employeur. Elle n’est pas un agrément systématique de toute embauche. La simplification des preuves de R242-3 ne prive personne de cette garantie, ni des remboursements et droits à retraite antérieurs.'),
'R243-27':('Conserve le guichet de paiement des revenus de remplacement et la simultanéité avec leur déclaration mensuelle.','L’échéance du dixième jour renvoie à R133-14-1 sans ajouter de déclaration distincte. La règle préserve le recouvrement des pensions et autres revenus en respectant leurs exonérations et leurs taux autonomes. Modifier ce seul calendrier ne démontre ni baisse de cotisation ni simplification supplémentaire ; aucun nouveau guichet ou dépôt n’est créé.'),
'R243-28':('Conserve le renvoi cohérent au recouvrement des revenus de remplacement, y compris les garanties et remises applicables.','L’assimilation technique des revenus aux rémunérations pour le recouvrement ne transforme pas les pensions en salaires privés soumis à la baisse ciblée de CSG. Les exonérations et taux de fond ne sont pas modifiés ; l’adaptation de Saint-Pierre-et-Miquelon et les périodes d’application des notes restent disponibles. Supprimer le bloc ferait aussi perdre les garanties et possibilités de remise.')}
assert len(kept)==19
for n,(decision,analysis)in kept.items():
 add(n,None,decision,base_review+' '+analysis,analysis+' Le maintien est intégral, y compris pour les situations futures éligibles ; les notes officielles restent attachées à la source.',
 'retained_necessary',decision+' '+analysis,base_limits,
 'Aucune charge ni formalité nouvelle n’est créée : le corps officiel reste intégralement inchangé, avec ses champs, exceptions, délais et garanties. Ce maintien ne vaut ni suppression de prélèvement ni nouvelle simplification démontrée.')
ordered=[rows[s['number']]for s in sources];assert len(ordered)==24
validate_answer(ordered,sources)
(P/'answer.json').write_text(json.dumps(ordered,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'articles':len(ordered),'rewrites':[r['number']for r in ordered if r['proposed_xml']is not None],'retained':[r['number']for r in ordered if r['proposed_xml']is None],'assessments':{r['number']:r['substantive_impact']['classification']for r in ordered},'answer_sha256':sha((P/'answer.json').read_bytes())},ensure_ascii=False,indent=2))
